<template><div class="p-2 receivable-page">
 <el-alert v-if="!projectId" title="请先在顶部选择当前物业项目" type="info" :closable="false" show-icon class="mb-2"/>
 <template v-else><el-card class="mb-2"><el-form :model="query" inline><el-form-item label="当前项目"><el-input :model-value="projectName" disabled/></el-form-item><el-form-item label="生成月份"><el-date-picker v-model="query.generateMonth" type="month" value-format="YYYY-MM-DD" clearable/></el-form-item><el-form-item label="房屋"><el-input v-model="query.roomKeyword" clearable/></el-form-item><el-form-item label="收费项目"><el-select v-model="query.chargeItemId" clearable><el-option v-for="x in items" :key="x.id" :label="x.itemName" :value="x.id"/></el-select></el-form-item><el-form-item label="责任人"><el-input v-model="query.responsibleCustomerKeyword" clearable/></el-form-item><el-form-item label="支付状态"><el-select v-model="query.paymentStatus" clearable><el-option v-for="x in pm_payment_status" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item><el-form-item><el-checkbox v-model="query.overdueOnly">仅逾期</el-checkbox></el-form-item><el-form-item><el-button type="primary" @click="search">搜索</el-button><el-button @click="reset">重置</el-button></el-form-item></el-form></el-card>
 <el-row :gutter="12" class="mb-2"><el-col v-for="x in cards" :key="x.label" :span="6"><el-card shadow="never"><div class="summary-label">{{x.label}}</div><div class="summary-value">¥ {{money(x.value)}}</div></el-card></el-col></el-row>
 <el-card><template #header><el-row :gutter="10"><el-col :span="1.5"><el-button v-hasPermi="['property:receivable:generate']" type="primary" @click="openGenerate">生成应收</el-button></el-col><el-col :span="1.5"><el-button v-hasPermi="['property:receivable:export']" type="warning" plain @click="doExport">导出</el-button></el-col><el-col :span="1.5"><el-button plain @click="openBatches">生成记录</el-button></el-col><right-toolbar v-model:show-search="showSearch" @query-table="load"/></el-row></template>
  <el-table v-loading="loading" :data="rows" border><el-table-column label="应收编号" min-width="190"><template #default="s"><el-button link type="primary" v-hasPermi="['property:receivable:query']" @click="openDetail(s.row)">{{s.row.receivableNo}}</el-button></template></el-table-column><el-table-column label="房屋" prop="roomFullNameSnapshot" min-width="150"/><el-table-column label="收费项目" prop="chargeItemNameSnapshot" min-width="140"/><el-table-column label="责任人" prop="responsibleCustomerNameSnapshot" min-width="100"/><el-table-column label="收费周期" min-width="190"><template #default="s">{{s.row.periodStartDate}} ~ {{s.row.periodEndDate}}</template></el-table-column><el-table-column label="应收" align="right"><template #default="s">{{money(s.row.receivableAmount)}}</template></el-table-column><el-table-column label="已收" align="right"><template #default="s">{{money(s.row.paidAmount)}}</template></el-table-column><el-table-column label="未收" align="right"><template #default="s">{{money(s.row.outstandingAmount)}}</template></el-table-column><el-table-column label="应缴日期" prop="dueDate" width="115"/><el-table-column label="支付状态" width="100"><template #default="s"><dict-tag :options="pm_payment_status" :value="s.row.paymentStatus"/></template></el-table-column><el-table-column label="逾期" width="80"><template #default="s"><el-tag :type="s.row.overdue?'danger':'success'">{{s.row.overdue?'逾期':'未逾期'}}</el-tag></template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="s"><el-button v-if="s.row.paymentStatus==='UNPAID'&&Number(s.row.paidAmount)===0" v-hasPermi="['property:receivable:cancel']" link type="danger" @click="cancelRow(s.row)">作废</el-button></template></el-table-column></el-table><pagination v-show="total>0" v-model:page="query.pageNum" v-model:limit="query.pageSize" :total="total" @pagination="load"/>
 </el-card></template>
 <el-dialog v-model="generateVisible" title="生成应收" width="560px"><el-form label-width="100px"><el-form-item label="当前项目"><el-input :model-value="projectName" disabled/></el-form-item><el-form-item label="生成月份"><el-date-picker v-model="generateMonth" type="month" value-format="YYYY-MM" :disabled-date="disableFutureMonth"/></el-form-item><el-alert title="已存在的相同收费周期不会重复生成；历史未缴账单不会阻止新周期生成。" type="info" :closable="false"/></el-form><template #footer><el-button @click="generateVisible=false">取消</el-button><el-button type="primary" :loading="generating" @click="submitGenerate">确认生成</el-button></template></el-dialog>
 <el-dialog v-model="resultVisible" title="生成结果" width="600px"><el-descriptions v-if="generationResult" :column="2" border><el-descriptions-item label="批次号">{{generationResult.batchNo}}</el-descriptions-item><el-descriptions-item label="状态"><dict-tag :options="pm_receivable_batch_status" :value="generationResult.status"/></el-descriptions-item><el-descriptions-item label="扫描">{{generationResult.scannedCount}}</el-descriptions-item><el-descriptions-item label="生成">{{generationResult.generatedCount}}</el-descriptions-item><el-descriptions-item label="已有跳过">{{generationResult.skippedExistingCount}}</el-descriptions-item><el-descriptions-item label="无需生成">{{generationResult.skippedNotDueCount}}</el-descriptions-item><el-descriptions-item label="失败">{{generationResult.failedCount}}</el-descriptions-item><el-descriptions-item label="摘要">{{generationResult.errorMessage||'-'}}</el-descriptions-item></el-descriptions></el-dialog>
 <el-dialog v-model="detailVisible" title="应收详情" width="850px"><el-descriptions v-if="detail" :column="2" border class="mb-3"><el-descriptions-item label="应收编号">{{detail.receivableNo}}</el-descriptions-item><el-descriptions-item label="项目">{{detail.projectName}}</el-descriptions-item><el-descriptions-item label="房屋快照">{{detail.roomFullNameSnapshot}}</el-descriptions-item><el-descriptions-item label="责任主体快照">{{detail.responsibleCustomerNameSnapshot}}</el-descriptions-item><el-descriptions-item label="收费项目快照">{{detail.chargeItemNameSnapshot}}</el-descriptions-item><el-descriptions-item label="计费规则快照">{{detail.chargeRuleNameSnapshot}}</el-descriptions-item><el-descriptions-item label="实际周期">{{detail.periodStartDate}} ~ {{detail.periodEndDate}}</el-descriptions-item><el-descriptions-item label="理论周期">{{detail.theoreticalStartDate}} ~ {{detail.theoreticalEndDate}}</el-descriptions-item><el-descriptions-item label="天数">{{detail.actualDays}} / {{detail.theoreticalDays}}</el-descriptions-item><el-descriptions-item label="账单/计价周期">{{detail.billingCycleSnapshot}} / {{detail.priceCycleSnapshot}}</el-descriptions-item><el-descriptions-item label="计价快照">{{priceExplanation(detail)}}</el-descriptions-item><el-descriptions-item label="应收/已收/未收">{{money(detail.receivableAmount)}} / {{money(detail.paidAmount)}} / {{money(detail.outstandingAmount)}}</el-descriptions-item><el-descriptions-item label="应缴日期">{{detail.dueDate}}</el-descriptions-item><el-descriptions-item label="逾期">{{detail.overdue?'逾期':'未逾期'}}</el-descriptions-item><el-descriptions-item label="支付状态"><dict-tag :options="pm_payment_status" :value="detail.paymentStatus"/></el-descriptions-item><el-descriptions-item label="批次号">{{detail.batchNo}}</el-descriptions-item><el-descriptions-item v-if="detail.paymentStatus==='CANCELLED'" label="作废原因">{{detail.cancelReason}}</el-descriptions-item></el-descriptions><h4>收款历史</h4><el-table :data="paymentHistory" border><el-table-column label="收款编号" prop="paymentNo" min-width="180"/><el-table-column label="付款人" prop="payerNameSnapshot"/><el-table-column label="收款时间" prop="paymentTime" min-width="170"/><el-table-column label="收款方式"><template #default="s"><dict-tag :options="pm_payment_method" :value="s.row.paymentMethod"/></template></el-table-column><el-table-column label="本次核销" align="right"><template #default="s">{{money(s.row.allocationAmount)}}<div v-if="s.row.paymentStatus==='REVERSED'" class="history-invalid">已随收款冲销失效</div></template></el-table-column><el-table-column label="收款状态"><template #default="s"><dict-tag :options="pm_payment_record_status" :value="s.row.paymentStatus"/></template></el-table-column></el-table></el-dialog>
 <el-drawer v-model="batchVisible" title="生成记录" size="70%"><el-table :data="batches" border><el-table-column label="批次号" prop="batchNo" min-width="190"/><el-table-column label="生成月份" prop="generateMonth"/><el-table-column label="状态"><template #default="s"><dict-tag :options="pm_receivable_batch_status" :value="s.row.status"/></template></el-table-column><el-table-column label="扫描" prop="scannedCount"/><el-table-column label="生成" prop="generatedCount"/><el-table-column label="已有" prop="skippedExistingCount"/><el-table-column label="无需" prop="skippedNotDueCount"/><el-table-column label="失败" prop="failedCount"/><el-table-column label="开始时间" prop="startedAt" min-width="170"/><el-table-column label="结束时间" prop="finishedAt" min-width="170"/><el-table-column label="错误摘要" prop="errorMessage" min-width="200"/></el-table></el-drawer>
</div></template>
<script setup name="Receivable" lang="ts">
import {cancelReceivable,exportReceivable,generateReceivable,getReceivable,getReceivablePayments,getReceivableSummary,listReceivable,listReceivableBatch,receivableContextChargeItems} from '@/api/property/charge/receivable';import type {ReceivableBatchVO,ReceivableGenerationResultVO,ReceivablePaymentVO,ReceivableQuery,ReceivableSummaryVO,ReceivableVO} from '@/api/property/charge/receivable/types';import type {ChargeItemOptionVO} from '@/api/property/charge/item/types';import modal from '@/plugins/modal';import {useCurrentProjectStore} from '@/store/modules/currentProject';import {useDict} from '@/utils/dict';import {useSearchToggle} from '@/hooks/form/useSearchToggle';
const {pm_payment_status,pm_payment_method,pm_receivable_batch_status,pm_payment_record_status}=toRefs<any>(useDict('pm_payment_status','pm_payment_method','pm_receivable_batch_status','pm_payment_record_status'));const store=useCurrentProjectStore(),projectId=computed(()=>store.currentProjectId),projectName=computed(()=>store.currentProjectName),rows=ref<ReceivableVO[]>([]),items=ref<ChargeItemOptionVO[]>([]),batches=ref<ReceivableBatchVO[]>([]),paymentHistory=ref<ReceivablePaymentVO[]>([]),summary=ref<ReceivableSummaryVO>({receivableTotal:0,paidTotal:0,outstandingTotal:0,overdueOutstandingTotal:0}),total=ref(0),loading=ref(false),generateVisible=ref(false),resultVisible=ref(false),detailVisible=ref(false),batchVisible=ref(false),generating=ref(false),generateMonth=ref(''),generationResult=ref<ReceivableGenerationResultVO>(),detail=ref<ReceivableVO>();const query=ref<ReceivableQuery>({pageNum:1,pageSize:10});const {showSearch}=useSearchToggle();let version=0;const cards=computed(()=>[{label:'应收总额',value:summary.value.receivableTotal},{label:'已收总额',value:summary.value.paidTotal},{label:'未收总额',value:summary.value.outstandingTotal},{label:'逾期未收',value:summary.value.overdueOutstandingTotal}]);
async function load(){const p=projectId.value,v=++version;if(!p){rows.value=[];return}loading.value=true;try{const [coreResult,optionResult]=await Promise.allSettled([Promise.all([listReceivable({...query.value,projectId:p}),getReceivableSummary({...query.value,projectId:p})]),receivableContextChargeItems(p)]);if(v!==version||String(p)!==String(projectId.value))return;if(coreResult.status==='fulfilled'){const [list,sum]=coreResult.value;rows.value=list.data.rows||[];total.value=list.data.total||0;summary.value=sum.data}else{throw coreResult.reason}if(optionResult.status==='fulfilled'){items.value=optionResult.value.data||[]}else{items.value=[];modal.msgWarning('应收数据已加载，但收费项目筛选项加载失败，请检查应收查询权限配置')}}finally{if(v===version)loading.value=false}}
const search=()=>{query.value.pageNum=1;load()};const reset=()=>{query.value={pageNum:1,pageSize:10};load()};const money=(v?:number)=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});const doExport=()=>projectId.value&&exportReceivable({...query.value,projectId:projectId.value});function openGenerate(){if(!projectId.value)return modal.msgWarning('请先选择项目');generateMonth.value=new Date().toISOString().slice(0,7);generateVisible.value=true}const disableFutureMonth=(d:Date)=>d>new Date(new Date().getFullYear(),new Date().getMonth()+4,0);
async function submitGenerate(){const p=projectId.value;if(!p||!generateMonth.value)return modal.msgWarning('请选择生成月份');generating.value=true;try{const r=await generateReceivable({projectId:p,generateMonth:generateMonth.value});if(String(p)!==String(projectId.value))return;generationResult.value=r.data;generateVisible.value=false;resultVisible.value=true;const failed=r.data.failedCount;failed?modal.msgWarning(`成功生成${r.data.generatedCount}笔，${failed}笔失败`):modal.msgSuccess(`成功生成${r.data.generatedCount}笔`);await Promise.all([load(),loadBatches()])}finally{generating.value=false}}
async function openDetail(row:any){const p=projectId.value,v=version;const [r,h]=await Promise.all([getReceivable(row.id),getReceivablePayments(row.id)]);if(v===version&&String(p)===String(projectId.value)){detail.value=r.data;paymentHistory.value=h.data||[];detailVisible.value=true}}
async function cancelRow(row:any){const result=await ElMessageBox.prompt(`作废 ${row.receivableNo}（${row.roomFullNameSnapshot}，${row.periodStartDate}~${row.periodEndDate}，¥${money(row.receivableAmount)}）。作废后原记录保留，可重新生成该周期。`,'作废应收',{inputPlaceholder:'请输入作废原因',inputValidator:(v)=>v.trim().length>=2&&v.length<=500||'作废原因长度必须在2到500字符之间'});await cancelReceivable(row.id,result.value);modal.msgSuccess('作废成功');await load()}
async function loadBatches(){const p=projectId.value;if(!p)return;const r=await listReceivableBatch({projectId:p,pageNum:1,pageSize:50});if(String(p)===String(projectId.value))batches.value=r.data.rows||[]}function openBatches(){batchVisible.value=true;loadBatches()}const priceExplanation=(r:ReceivableVO)=>r.billingMethodSnapshot==='AREA'?`${r.areaSnapshot}㎡ × ${r.unitPriceSnapshot}元/㎡/${r.priceCycleSnapshot}；${r.actualDays}/${r.theoreticalDays}天 = ${money(r.receivableAmount)}元`:`固定金额 ${r.fixedAmountSnapshot}元/${r.priceCycleSnapshot}；${r.actualDays}/${r.theoreticalDays}天 = ${money(r.receivableAmount)}元`;
watch(projectId,()=>{version++;rows.value=[];items.value=[];detailVisible.value=false;generateVisible.value=false;resultVisible.value=false;batchVisible.value=false;query.value={pageNum:1,pageSize:10};load()});onMounted(load);onBeforeUnmount(()=>version++);
</script><style scoped>.summary-label{color:var(--el-text-color-secondary)}.summary-value{font-size:22px;font-weight:600;margin-top:8px}.history-invalid{color:var(--el-color-danger);font-size:12px}.receivable-page :deep(.el-select){width:180px}</style>
